    # A solid row or column separates two equally sized patterns.
    for r in range(h):
        if len(set(grid[r])) == 1:
            top, bottom = grid[:r], grid[r + 1:]
            a, b = (top, bottom) if len(top) <= len(bottom) else (bottom, top)
            return [
                [2 if a[i][j] != 0 and b[i][j] != 0 else 0
                 for j in range(w)]
                for i in range(len(a))
            ]

    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            a, b = (left, right) if len(left[0]) <= len(right[0]) else (right, left)
            return [
                [2 if a[i][j] != 0 and b[i][j] != 0 else 0
                 for j in range(len(a[0]))]
                for i in range(h)
            ]

